---FreshUI
---@param cardInfo table{
---     cardDojo: CardDojo
---     cafeEnergy: number
---     maxEnergy: number
---}
function OverManegeLoungeCardDetailsStrokeNode:FreshUI(cardInfo)
    ---@type CardDojo
    local cardDojo = cardInfo.cardDojo
    self._cardDojo = cardDojo
    self._playerCardId = checkNumber(cardDojo.id)
    local cardId   = cardDojo.cardId
    
    ---@type MaidCoffeeCardInfoVo
    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
    self.ImgBuff.Status = vo.job

    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    ---刷新卡牌信息
    self:FreshCardInfo(cardVo, cardDojo)

    ---刷新卡牌心情
    self:FreshMood(cardDojo.cafeEnergy, cardInfo.maxEnergy)
    self:OnEventTimeChange(false)
    
end

function OverManegeLoungeCardDetailsStrokeNode:FreshCardInfo(cardVo, cardDojo)
    self.TextName1.text = cardVo.name
    self.TextName2.text = cardVo.descr

    UICommonUtils.FillCardHeadNode(self.CommonSmallHeadNode, 1, nil, cardDojo, true)
end

function OverManegeLoungeCardDetailsStrokeNode:FreshMood(cafeEnergy, maxEnergy, isDetail)
    local status = MaidCoffeeUtils.GetCardMoodStatus(checkNumber(cafeEnergy))
    local ImgAttribute = self.ImgAttribute
    ImgAttribute.Status = status

    local TextNumber = self.TextNumber
    local color = MaidCoffeeConstants.CardMoodStatusColor[status] or MaidCoffeeConstants.CardMoodStatusColor[1]
    TextNumber.text = string.format("<color=%s>%s</color>/%s", color, cafeEnergy, maxEnergy)
    
end

