--region handler

function OverManegeLoungeCardDetailsStrokeNode:OnEventTimeChange(isChange)
    local cardInfo = self._dataProviderIns:GetCardInfoByPlayerCardId(self._playerCardId)
    local seconds = cardInfo.recoveryTime - os.time()
    local isShow = seconds > 0
    if isShow ~= self._isShowTime then
        self._isShowTime = isShow 
        GameUtils.UpdateUIShowState(self.Time.gameObject, isShow)
    end
    if isShow then
        self.TextNumberTime.text = GetTimeHMS9(seconds)
    end
    if isChange then
        self:FreshMood(cardInfo.cafeEnergy, cardInfo.maxEnergy)
    end
    
end

--region handler

return OverManegeLoungeCardDetailsStrokeNode